// Derived indexes built at load time
const INFINITIVES = [...new Set(VERB_DB.map(r => r.infinitive))];

const VERB_BY_INFINITIVE = VERB_DB.reduce((acc, row) => {
  if (!acc[row.infinitive]) acc[row.infinitive] = [];
  acc[row.infinitive].push(row);
  return acc;
}, {});

// Returns all rows for a given infinitive
function getVerbRows(infinitive) {
  return VERB_BY_INFINITIVE[infinitive] || [];
}

// Returns the single row matching infinitive+mood+tense
function getConjugation(infinitive, mood, tense) {
  return (VERB_BY_INFINITIVE[infinitive] || []).find(r => r.mood === mood && r.tense === tense);
}

// Returns count random infinitives excluding the given list
function getRandomVerbs(count, exclude = []) {
  const pool = INFINITIVES.filter(v => !exclude.includes(v));
  const shuffled = pool.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

// Returns all rows for a given mood+tense
function getVerbsForTense(mood, tense) {
  return VERB_DB.filter(r => r.mood === mood && r.tense === tense);
}
